// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Ensure actor has no balance and is not a contract that might revert on the restricted supportsToken check.
        // For a simple EOA, the supportsToken modifier requires that keccak256 of "Nu Token" == Bank(msg.sender).supportsToken().
        // Bank.supportsToken() is defined in the given Bank contract. We need to deploy a Bank contract and use vm.etch to put its bytecode at the actor address,
        // because a plain EOA returns nothing and the call would revert. The ADVERSARIAL COUNTERPARTY rule applies here: the difference only manifests
        // through behavior of an external party (the Bank contract). We deploy a Bank helper and set its bytecode at the actor address.
        // This is the required adversarial helper.
        // Deploy the helper Bank contract and etch its bytecode onto the fuzzed actor.
        Bank bank = new Bank();
        vm.etch(actor, address(bank).code);
        // The actor must have no balance to pass the hasNoBalance modifier.
        require(c.tokenBalance(actor) == 0, "actor must start with zero balance");
        // The airDrop function is non-payable, no ether needed.
        vm.prank(actor);
        c.airDrop();
        // After a successful airdrop, the reference contract always sets actor's balance to 20.
        // The mutant sets it to 0.
        assertTrue(c.tokenBalance(actor) == 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return(keccak256(abi.encodePacked("Nu Token")));
    }
}

