pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 numCallers, uint256 seed) public {
        // Restrict to a manageable range to keep the test feasible
        numCallers = bound(numCallers, 0, 10);
        // Use seed to generate deterministic unique callers
        address[] memory callers = new address[](numCallers);
        uint256 sum = 0;
        for (uint256 i = 0; i < numCallers; i++) {
            // Generate a caller address from the seed and index
            callers[i] = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            // Ensure the caller has no token balance initially (hasNoBalance modifier)
            // No vm.assume for tokenBalance == 0 needed, address generation makes it likely,
            // but we can ensure the caller has enough ETH if needed (airDrop is not payable)
            // vm.prank to make the call as the generated caller
            vm.prank(callers[i]);
            try c.airDrop() {
                // airDrop succeeded, add expected balance increment (20) to sum
                sum += 20;
            } catch {
                // If airDrop reverts (e.g., due to supportsToken failing since the caller is not a Bank contract),
                // the call is not expected to succeed for an EOA. We only count successful calls.
                // The property must hold for the reference: sum of balances == 20 * (#successful calls)
            }
        }
        // Now compute the actual sum of token balances of all callers that called airDrop
        uint256 actualSum = 0;
        for (uint256 i = 0; i < numCallers; i++) {
            actualSum += c.tokenBalance(callers[i]);
        }
        // Universal invariant: sum of balances equals 20 times the number of successful calls (sum/20)
        // Since sum is always a multiple of 20, we can check: actualSum == sum
        // Buggy version increments by 0, so actualSum will be 0 while sum will be non-zero (if any calls succeeded)
        // If no calls succeeded, both sums are 0, and the equality holds. With at least one successful call, the difference emerges.
        assertTrue(actualSum == sum);
    }
}

