pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller) public {
        // Ensure the caller's tokenBalance starts at 0 to satisfy the hasNoBalance modifier.
        assertEq(c.tokenBalance(caller), 0);

        // Execute airDrop as the fuzzed caller.
        vm.prank(caller);
        bool ok = true;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the airDrop did not revert, the caller's tokenBalance must be exactly 20.
        if (ok) {
            assertEq(c.tokenBalance(caller), 20);
        } else {
            // If it reverted, balance must remain 0.
            assertEq(c.tokenBalance(caller), 0);
        }
    }
}

