pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint8 otherNum) public {
        vm.assume(caller != address(0));
        vm.assume(otherNum > 0);
        address other = address(uint160(uint256(keccak256(abi.encodePacked(otherNum)))));
        vm.assume(other != caller);
        vm.assume(other != address(0));

        vm.prank(other);
        c.airDrop();
        uint256 otherPreBalance = c.tokenBalance(other);
        require(otherPreBalance == 20, "setup failed");

        vm.prank(caller);
        bool ok = true;
        try c.airDrop() { ok = true; } catch { ok = false; }

        if (ok) {
            assertEq(c.tokenBalance(other), otherPreBalance);
        } else {
            assertTrue(true);
        }
    }
}

